    -- Chapter: Light - Reflection and Refraction (Seq: 9)
    SELECT id INTO v_chapter_id FROM chapters WHERE subject_id = v_subject_id AND sequence_number = 9 LIMIT 1;
    IF v_chapter_id IS NOT NULL THEN
        DELETE FROM quizzes WHERE chapter_id = v_chapter_id AND quiz_kind = 'pyq_practice';
        INSERT INTO quizzes (chapter_id, title, quiz_kind, total_marks)
        VALUES (v_chapter_id, 'Previous Years Board Questions', 'pyq_practice', 0)
        RETURNING id INTO v_quiz_id;

        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'An object is placed at a distance of 20 cm from the optical centre of a concave lens and its image is formed on the same side of the lens as the object. If the distance of the image from optical centre of the lens is 10 cm, use lens formula to determine (i) focal length, and (ii) power of the lens in new Cartesian sign conventions. 3', 'short_answer', 1, '2025, 2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Mirror ‘X’ is used to concentrate sunlight in solar furnace and Mirror ‘Y’ is fitted on the side of the vehicle to see the traffic behind the driver. Which of the following statements are true for the two mirrors ? (i) The image formed by mirror ‘X’ is real, diminished and at its focus. (ii) The image formed by mirror ‘Y’ is virtual, diminished and erect. (iii) The image formed by mirror ‘X’ is virtual, diminished and erect. (iv) The image formed by mirror ‘Y’ is real, diminished and at its focus. (A) (i) and (ii) (B) (ii) and (iii) (C) (iii) and (iv) (D) (i) and (iv) For Questions number 1 7 to 20, two statements are given — one labelled as Assertion (A) and the other labelled as Reason (R). Select the correct answer to these questions from the codes (A), (B), (C) and ( D) as given below. (A) Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of Assertion (A). (B) Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of Assertion (A). (C) Assertion (A) is true, but Reason (R) is false. (D) Assertion (A) is false, but Reason (R) is true.', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Draw ray diagrams to show the nature, position and relative size of the image formed by a convex mirror when the object is placed (i) at infinity and (ii) between infinity and pole P of the mirror. 3', 'short_answer', 3, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(a) (i) The power of a lens ‘X’ is – 2·5 D. Name the lens and determine its focal length in cm. For which eye defect of vision will an optician prescribe this type of lens as a corrective lens ? (ii) ‘‘The value of magnification ‘m’ for a lens is – 2.’’ Using new Cartesian Sign Convention and considering that an object is placed at a distance of 20 cm from the optical centre of this lens, state : (I) the nature of the image formed; (II) size of the image compared to the size of the object; (III) position of the image, and (IV) sign of the height of the image. (iii) The numerical values of the focal lengths of two lenses A and B are 10 cm and 20 cm respectively. Which one of the two will show higher degree of convergence/divergence ? Give reason to justify your answer. 5 OR (b) (i) Draw a ray diagram to show the refraction of a ray of light through a rectangular glass slab when it falls obliquely from air into glass. (ii) State Snell’s law of refraction of light. (iii) Differentiate between the virtual images formed by a convex lens and a concave lens on the basis of : (I) object distance, and (II) magnification. 5', 'short_answer', 5, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'If the absolute refractive indices of two media X and Y are 6 5 and 4 3 respectively, then the refractive index of Y with respect to X will be : (A) 10 9 (B) 9 10 (C) 9 8 (D) 8 9', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(a) Out of the two lenses, one concave and the other convex, state which one will diverge a parallel beam of light falling on it. Draw a ray diagram to show the principal focus of the lens. 2 OR (b) A ray of light after refraction from a convex lens emerges parallel to its principal axis. 2 (i) Draw a labelled ray diagram to show it. (ii) In this case, the incident ray before refraction from the lens passes through a point on its principal axis. Name the point.', 'short_answer', 2, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(a) A student has difficulty in reading his textbooks but can read the blackboard clearly while sitting in the last row. Name the defect of vision the student is suffering from. List two reasons due to which this defect arises. Write the nature of the lenses required to correct this defect. 2 OR (b) Draw a ray diagram to show the path of a ray of light falling obliquely on one of the refracting faces of a triangular glass prism and mark the angle of deviation on it. 2', 'short_answer', 2, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(a) (i) ‘‘In refraction of light through a rectangular glass slab, the emergent ray is always parallel to the direction of the incident ray.’’ Why ? Explain with the help of a ray diagram. What happens when a ray of light falls normally on one of the faces of a rectangular glass prism ? Draw diagram. (ii) An object is placed at a distance of 30 cm from the optical centre of a concave lens of focal length 20 cm. Use Lens formula to determine the position of the image formed in this case. 5 OR (b) (i) A student wishes to study the image formation by a con cave mirror using candle flame as object. State the type of the image formed by the mirror and mention the change in the image formed, if any, that he observes when the candle flame is gradually moved away from the pole of the mirror. Draw a ray diagram to show the image formation when the object distance is nearly equal to the radius of curvature of the mirror. (ii) A convex mirror used for rear -view on an automobile has a focal length of 3∙0 m. If a bus is located at 6∙0 m from this mirror, use mirror formula to find the position of the image of the bus as seen in the mirror. 5', 'short_answer', 5, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Explain the phenomenon of rainbow formation in the sky. Draw the labelled ray diagram in support of your explanation. 3 37. 3 { } 31/4/1 Page 28 of 32             : (a)   K     ,   AB       ? (b)              AB         38.                             ,                                                            ,           4 (a)                ? (b)              ? (c)        (    )      ?       (c)             ? { } 31/4/1 Page 29 of 32 P.T.O. On the basis of the given circuit arrangement, answer the following questions : (a) What happens to the rod AB when the key K is closed and why ? (b) Name and state the rule that determines this behaviour of the rod AB in the above situation. 38. The above ray diagram is to show image formation by a reflecting telescope. Reflecting telescope revolutionized our way of looking into the sky. Reflecting telescopes employ large mirrors to gather and focus light rather than relying solely on lenses as we do in the refracting telescopes. These telescopes utilize precisely shaped and polished mirrors to capture incoming light and reflect it to a focal point, where the telescope forms an image for observation. 4 (a) What kind of image of a star is seen by the observer in the eye-piece ? (b) What kind of mirror is used in this reflecting telescope ? (c) Explain with the reason, what kind of optical device (type of lens or mirror) is used at the eye-piece. OR (c) What is the role of plane mirror in image formation by this telescope ? { } 31/4/1 Page 30 of 32', 'short_answer', 4, '2026', 'medium');
