        VALUES (v_quiz_id, 'From the following options choose the one which gives negative magnification greater than one : 1 (A) Concave mirror; Nature of image – real (B) Concave mirror; Nature of image – virtual (C) Convex mirror; Nature of image – real (D) Convex mirror; Nature of image – virtual For Question number 32, two statements are given — one labelled as Assertion (A) and the other labelled as Reason (R). Select the correct answer to this question from the codes (A), (B), (C) and (D) as given below. (A) Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of Assertion (A). (B) Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of Assertion (A). (C) Assertion (A) is true, but Reason (R) is false. (D) Assertion (A) is false, but Reason (R) is true.', 'short_answer', 3, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Attempt either (a) or (b) : (a) How does the focal length of eye lens change as the distance of the object from the eyes is altered ? Explain. 2 OR (b) Why is the concave lens used as a corrective lens for a myopic eye ? 2 35. (a) State the laws which help to find out the angle of incidence and angle of reflection in the ray diagram given above. (b) Find out the angle of incidence and angle of reflection in the given ray diagram. 3 [ ] 31/2/2 Page 28 of 31', 'short_answer', 2, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'The growth of tendrils in grapes plants is due to : 1 (A) Effect of light (B) Effect of gravity (C) Rapid cell division in tendril cells in contact with the support (D) Rapid cell division in tendril cells that are away from the support For Questions number 8 and 9, two statements are given — one labelled as Assertion (A) and the other labelled as Reason (R). Select the correct answer to these questions from the codes (A), (B), (C) and ( D) as given below. (A) Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of Assertion (A). (B) Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of Assertion (A). (C) Assertion (A) is true, but Reason (R) is false. (D) Assertion (A) is false, but Reason (R) is true.', 'short_answer', 1, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Absolute refractive index of water and glass is 4 3 and 3 2 respectively. If the speed of light in glass is 2  108 m/s, the speed of light in water is : (A) 9 4 m/s (B) 7 3 m/s (C) 16 9 m/s (D) 9 8 m/s', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'When a beam of white light passes through a region of very fine dust particles, the colour of light that scatters the most in that region is : (A) red (B) orange (C) blue (D) yellow', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(a) Write the name of the lens and position of the object in front of it so that a virtual and magnified image is formed. (b) An object is placed perpendicular to the principal axis of a convex lens of focal length 20 cm . If object is located at 30 cm from this lens, using lens formula find out the position and nature of the image formed. 3', 'short_answer', 3, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Observe the given ray diagram showing refraction through a prism and choose the correct option for colour of rays 1 and 2 : 1 Colour of ray 1 Colour of ray 2 (A) Blue Red (B) Green Yellow (C) Red Violet (D) Violet Red For Question number 32, two statements are given — one labelled as Assertion (A) and the other labelled as Reason (R). Select the correct answer to this question from the codes (A), (B), (C) and (D) as given below. (A) Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of Assertion (A). (B) Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of Assertion (A). (C) Assertion (A) is true, but Reason (R) is false. (D) Assertion (A) is false, but Reason (R) is true. [ ] 31/3/1 Page 24 of 31', 'short_answer', 3, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'The variation of image distance ( v) with the object distance ( u) for a convex lens is given in the following observation table. Analyse it and answer the questions given below : S.No. Object distance (u) cm Image distance (v) cm 1 – 150 + 30 2 – 75 + 37·5 3 – 50 + 50 4 – 37·5 + 75 5 – 30 + 150 6 – 15 + 37·5 (a) Without calculation, find out the focal length of the given convex lens. Justify your answer. 1 (b) Which one of the observation s given in the table is not correct and why ? 1 (c) (i) Find out the value of magnification for u = – 30 cm . Write the nature of the image formed. Give reason for your answer. 2 OR (c) (ii) Analyse the data given in the table above and draw the labelled ray diagram for u = – 30 cm and v = 150 cm. 2', 'short_answer', 2, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'A zygote is formed by the fusion of a male gamete and a female gamete. The number of chromosomes in the zygote of a human is : (A) 23 (B) 44 (C) 46 (D) 92 11. Absolute refractive index of glass and water is 23 and 34 respectively. If the speed of light in glass is 2 108 m/s, the speed of light in water is : (A) 49 108 m/s (B) 25 108 m/s (C) 37 108 m/s (D) 916 108 m/s 12. When a beam of white light passes through a region having very fine dust particles, the colour of light mainly scattered in that region is : (A) Red (B) Orange (C) Blue (D) Yellow 13. Consider the following combinations of resistors : The combinations having equivalent resistance 1 is/are : (A) I and IV (B) Only IV (C) I and II (D) I, II and III 14. An electric iron of resistance 20 draws a current of 5 A. The heat developed in the iron in 30 seconds is : (A) 15000 J (B) 6000 J (C) 1500 J (D) 3000 J 14-31/4/1 8', 'short_answer', 1, '2024', 'medium');
