        VALUES (v_quiz_id, 'Three resistors of 2 , 3  and 6  are connected in (i) series, and (ii) parallel. Draw the arrangements of the resistors and find the equivalent resistance of each arrangement. 3', 'short_answer', 3, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'A wire of length ‘l’ is gradually stretched so that its length increases to 3l. If its original resistance is R, then its new resistance will be : (A) 3R (B) 6R (C) 9R (D) 27R', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Read the following passage and answer the questions that follow : Swati, a class 10 student, observes that when she passes close to the refrigerator in her kitchen, she feels the heat, although the things kept inside the refrigerator are cool. (a) Describe the cause of heating in the above-mentioned case. 1 (b) A current I flows through a resistor of resistance R when the potential difference across it is V. Applying Ohm’s law, write the formula for amount of heat produced by the resistor in time t. 1 (c) (i) Write any two practical applications of heating effect of electric current. 2 OR (c) (ii) Define the commercial unit of electric energy and express it in Joules (J). 2', 'short_answer', 2, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
