        VALUES (v_quiz_id, 'A voltage source sends a current of 2 A to a resistor of 40  connected across it for 5 minutes. Calculate the electrical energy supplied by the source. 2', 'short_answer', 2, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Four resistors, each of resistance 2∙0 , are joined end to en d to form a square ABCD as shown. Using appropriate formula, determine the equivalent resistance of the combination between its two ends A and B. 2', 'short_answer', 2, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(a) Name and state the rule which determines the force on a current carrying conductor placed in a uniform magnetic field. (b) Consider the following three diagrams in which the entry of a positive charge (+Q) in a magnetic field is shown. Identify giving reason the case in which the force experienced by the charge is (i) maximum, and (ii) minimum. 3 I. II. III.', 'short_answer', 3, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(a) Define volt, the unit of potential difference. 2 (b) Calculate the work done required to move an electron between two points A and B located at a potential difference of 100 V in an electric field. { } 31/4/1 Page 26 of 32 35. (a)           : 3 (i)  A       B      (ii)  B   C     (b)         ‘A’   ,  ‘C’         ‘B’   ,  ‘A’   ‘C’       ', 'short_answer', 5, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(A) 5 (i) The given electric circuit is a part of an electrical device. Use the information given in the electric circuit diagram to calculate : (I) Potential difference across the ends of resistor R2. (II) Value of resistor R 2. (III) Value of resistor R 1. (ii) Write the factors on which resistance of a conductor depends and derive the formula for resistance of a given conductor. OR (B) (i) How much electric current will an electric iron draw from 220 V source if the resistance of its heating element when hot, is 55  ? Calculate the power consumed by the electric iron when it is operated at 220 V. (ii) In a house, 3 bulbs of 100 watt each, are lit for 5 hours daily and an electric heater of 1.0 kW is used for half an hour daily. Calculate the total energy consumed in a month of 30 days and its cost at the rate of ` 3.60 per kWh. (iii) With reason explain, why are alloys commonly used to make elements of electrical heating devices. _______________ { } 31/4/1 Page 32 of 32 1190-1', 'short_answer', 1, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(A) V-I graph for a nichrome wire is shown in the diagram. 5 (i) Prove that the graph follows Ohm’s law and calculate the resistance of nichrome wire from the given V-I graph. (ii) (I) Calculate the equivalent resistance of the combination of resistors connected in the given circuit. (II) Find the value of the total current drawn from the battery. OR (B) (i) Define the SI unit of power. Express the electric power of an electric appliance in terms of potential difference and current flowing through it. (ii) In a house, 3 bulbs of 100 W each, are lit for 5 hours daily and an electric heater of 1.0 kW is used for half an hour daily. Calculate the total energy consumed in a month of 30 days and its cost at the rate of ` 3.60 per kWh. (iii) Convert the commercial unit of electric energy into Joule (J). ___________ { } 31/4/2 Page 32 of 32 1190-2', 'short_answer', 2, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(a) State the law which gives the relation between the electric current flowing through a given conductor and the potential difference applied across it. 2 (b) Draw V-I graph for a given conductor as per the law stated in above question (a).', 'short_answer', 5, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(A) (i) Derive an expression for the equivalent resistance of three resistors connected in parallel with a battery as shown in figure. 5 (ii) Find the values of the electric currents flowing through the resistors R1, R2 and R3 in the given electric circuit. OR (B) (i) Define electrical resistivity of a material. (ii) How will the resistivity and resistance of a conducting wire change if the length and area of cross-section of wire both are doubled ? Justify your answer. (iii) Calculate the electric current flowing through a 4 resistor that produces 100 J of heat every second. ___________ { } 31/4/3 Page 32 of 32 1190-3', 'short_answer', 3, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Work done in displacing an electron between two points having potential difference of 1 V, is : 1 (A) – 1·6  10–19 C (B) – 1·6  10–19 J (C) + 1·6  10–19 J (D) – 1·6  10–19 V', 'short_answer', 3, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Attempt either subpart (a) or (b) : (a) (i) In a house , 5 fans, rated 100 W; 220 V each are used for 4 hours daily and an electric heater rated 1000 W; 220 V is used for 5 hours daily. Calculate the cost of electrical energy consumed by the fans and the electric heater in a month of 30 days if the cost of 1 unit of electrical energy is ₹ 5. [ ] 31(B) Page 26 of 27 [ ] 31(B) Page 27 of 27 P.T.O. (ii) You have two fuse wires X and Y with electric current rating 5 A and 10 A respectively. Which of the two would you use with a heater rated 2000 W; 220 V ? Justify your answer. 5 OR (b) (i) State the relationship of the resistance (R) of a wire with its area of cross -section (A) and its length ( l). With the help of this relation , define resistivity of the material of the wire. (ii) In an electric c ircuit, 2 A electric current flows through a 40  resistor for 50 seconds. (I) Calculate the heat produced in the wire. (II) If another 40  resistor is connected in parallel to the given 40  resistor, calculate the heat produced in the circuit in 50 seconds. 5', 'short_answer', 5, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'In an electric circuit carrying current I, a 2  resistor is replaced by an 8  resistor without changing the connected (ideal) battery. Then : 1 (A) current becomes 4 I and potential difference 4 V (B) current becomes 4 I and potential difference remains V (C) current becomes 4I and potential difference remains V (D) current becomes 4I and potential difference 4 V [ ] 31/3/2 Page 24 of 31', 'short_answer', 3, '2026', 'medium');
