        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Assertion (A) : The needle of a compass, kept in an external magnetic field, always aligns itself in the North -South direction of the Earth. Reason (R) : The b ehaviour of the needle of the compass is similar to the behaviour of a freely suspended bar magnet. 1 33. A ray of light enters into medium B from medium A as shown in the given figure : (a) Which one of the se two media is optically denser than the other medium ? Justify your answer. (b) If the speed of light in medium A is VA and in medium B is VB, then what is the refractive index of medium B with respect to medium A ? 2', 'short_answer', 3, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Assertion (A) : No two magnetic field lines are found to cross each other. Reason (R) : The compass needle cannot point towards two directions at the point of intersection of two magnetic field lines.', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Observe the given figures A and B. When chhui-mui (sensitive) plant is touched, its leaves fold. This is due to : Figure A Figure B (A) Hormonal effect (B) Thermal effect (C) Change in amount of water in cells (D) Electromagnetic effect', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(a) The given figure shows the current passing through the straight conductor XY. (i) Copy the diagram and draw the magnetic field lines when current flows from conductor X to Y. (ii) Name and state the rule used in determining the direction of the magnetic field lines in the situation given above. (iii) State Fleming’s left hand rule. Using this rule, determine the direction of force applied on an electron entering a uniform magnetic field as shown in the figure. 5 OR (b) (i) Define the term solenoid. Draw the pattern of the magnetic field lines in and around a current carrying straight solenoid. Mark on the pattern the (i) direction of current, (ii) direction of field lines near the ends of the solenoid, and (iii) region where the magnetic field is uniform. (ii) How would you make an electromagnet using a current carrying solenoid ? 5', 'short_answer', 5, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Which one of the following statements is not true about a bar magnet ? (A) It sets itself in north-south direction when suspended freely. (B) It has attractive power for iron filings. (C) It produces magnetic field lines. (D) The direction of magnetic field lines inside a bar magnet is from its north pole to its south pole.', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'The strength of the magnetic field produced inside a current carrying long straight solenoid does not depend upon : (A) Area of cross-section of the tube of the solenoid (B) Number of turns per unit length in the solenoid (C) Direction of current flowing through the coil of the solenoid (D) Material of the core of the solenoid', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Assertion (A) : Magnetic field lines around a bar magnet never intersect each other. Reason (R) : Magnetic field produced by a bar mag net is a quantity that has both magnitude and direction.', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Assertion (A) : With the help of compass, magnetic field lines can be traced outside the bar magnet. Reason (R) : The north pole of a compass needle always points towards the south pole of the magnet when brought close to it.', 'short_answer', 3, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(A) A fuse in electric circuit is rated 4 A. Can it be used with an electric heater of rating 2 kW, 200 V ? Explain your answer. 2 OR (B) How is an electromagnet made ? Write any two ways by which the strength of electromagnet can be increased. 2 { } 31/4/3 Page 26 of 32', 'short_answer', 2, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Assertion (A) : Direction of force exerted on a current -carrying conductor placed in a magnetic field remains same if the directions of both magnetic field and current flowing through the conductor are reversed. Reason (R) : The direction of force exerted on a current -carrying conductor placed in an external magnetic field can be determined by using magnetic compass. 1 33. With the help of above given ray diagram, calculate the angle of refraction. Given that the refractive index of Medium 2 with respect to Medium 1 is 3 . 2 [ ] 31/2/3 Page 26 of 31', 'short_answer', 3, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Attempt either (a) or (b) : (a) A person was repairing an electric heater. He observed that there were three different connecting wire s of three different colours in the cable attached to the heater. (i) What are these three different wires called ? Name them colourwise. (ii) What is the value of standard potential difference at which electricity is supplied in Indian homes for lighting ? (iii) What is the role of (I) earthing and (II) fuse in domestic electric circuits ? 5 OR (b) (i) Write the name and statement of the rule used to determine the direction of the : (I) force experienced by a straight current-carrying conductor placed in a uniform magnetic field perpendicular to the field. (II) magnetic field produced around a straight conductor carrying electric current. [ ] 31/3/3 Page 30 of 31 (A) (B) [ ] 31/3/3 Page 31 of 31 P.T.O. (ii) Two straight current -carrying conductors (A) and (B) are shown in the figures below : (A) (B) (I) Mark the direction of the magnetic field s around these current-carrying conductors (A) and (B). (II) Compare the strengths of magnetic fields produced (1) at points P and Q and ( 2) at points Q and R due to these current-carrying conductors, qualitatively. 5', 'short_answer', 5, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Consider the following combinations of resistors : The combinations having equivalent resistance 1 is/are : (A) I and IV (B) Only IV (C) I and II (D) I, II and III For Questions number 17 to 20, two statements are given one labelled as Assertion (A) and the other labelled as Reason (R). Select the correct answer to these questions from the codes (A), (B), (C) and (D) as given below. (A) Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of Assertion (A). (B) Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of Assertion (A). (C) Assertion (A) is true, but Reason (R) is false. (D) Assertion (A) is false, but Reason (R) is true. 17. Assertion (A) : Oxygen is essential for all aerobic forms of life. Reason (R) : Free oxygen atoms combine with molecular oxygen to form ozone. 18. Assertion (A) : Magnetic field lines never intersect each other. Reason (R) : If they intersect, then at the point of intersection, the compass needle would point towards two directions, which is not possible. 14-31/4/3 12', 'short_answer', 1, '2024', 'medium');
