        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'In our homes, we receive the supply of electric power through a main supply also called mains, either supported through overhead electric poles or by underground cables. In our country the potential difference between the two wires (live wire and neutral wire) of this supply is 220 V. (a) Write the colours of the insulation covers of the line wires through which supply comes to our homes. 1 (b) What should be the current rating of the electric circuit (220 V) so that an electric iron of 1 kW power rating can be operated ? 1 1 (c) (i) What is the function of the earth wire ? State the advantage of the earth wire in domestic electric appliances such as electric iron. 2 OR (c) (ii) List two precautions to be taken to avoid electrical accidents. State how these precautions prevent possible damage to the circuit/appliance. 2', 'short_answer', 2, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'An electric kettle is rated 750 W; 220 V. Can this kettle be used in a circuit which has a fuse of current rating 3 A ? Give reason for your answer. 2', 'short_answer', 2, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Consider a rectangular cardboard having two holes P and Q through which a current carrying circular loop has been inserted as shown in the diagram. (a) Make this diagram on your answer sheet and draw three magnetic field lines, one each passing through the points 1 (near P), 2 (at the centre of the loop) and 3 (near Q). (b) List two factors on which the intensity of the magnetic field produced at the centre of the loop depends. (c) Name the rule you will apply to determine the direction of magnetic field produced due to a current carrying straight conductor. 3', 'short_answer', 3, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(a) Draw a labelled diagram to show the pattern of magnetic field lines on a horizontal white board due to a straight current carrying conductor passing perpendicular through its centre. If the direction of current in the conductor is vertically downwards, mark the direction of (i) current, and (ii) magnetic field lines. (b) State the right hand thumb rule and check whether the directions marked on the diagram are in accordance with this rule. 3', 'short_answer', 3, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'In domestic electric circuits, the colour of insulation covers of wires in the cables of electric iron/electric toaster is generally : (A) red for live wire, green for neutral wire and black for earth wire (B) red for live wire, black for neutral wire and green for earth wire (C) green for live wire, black for neutral wire and red for earth wire (D) green for live wire, red for neutral wire and black for earth wire', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(A) (i) Draw a diagram showing the magnetic field lines around a bar magnet. Write any two characteristics of magnetic field lines. 5 (ii) Write the statement of Right hand thumb rule. (iii) The concentric circles representing the magnetic field around a current carrying straight wire become larger and larger as we move away from the wire. How does magnetic field change on these concentric circles ? OR (B) (i) Draw a diagram, showing the magnetic field lines in and around the current carrying solenoid. Write any two salient features of these lines. (ii) What is an electromagnet and how is it made ? ____________ { } 31/5/1 Page 32 of 32 1191-1', 'short_answer', 1, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(A) (i) List any two features of the electric current used in the houses of India. 5 (ii) Write any two differences between direct current and an alternating current. (iii) How will you identify live wire and neutral wire in a domestic electric circuit ? OR (B) (i) Why is fuse an important component in our electric circuits ? (ii) Distinguish between overloading and short-circuiting of a circuit. (iii) Giving reason explain what type of materials are used in fuse wires. ____________ { } 31/5/2 Page 32 of 32 1191-2', 'short_answer', 2, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(A) (i) State the rule which gives the direction of force acting on a current carrying conductor placed in a uniform magnetic field. 5 (ii) Name any two devices which work on the basis of an interaction between magnetic field and current carrying conductor. { } 31/5/3 Page 30 of 32 (iii)       :                        (B) (i)             (ii)    ,            ?       (iii) 220 V, 2200 W                    ? ____________ { } 31/5/3 Page 31 of 32 P.T.O. (iii) Observe the given diagrams : Comment on the magnitude of force on electron in both the cases and give reason for your answer. OR (B) (i) List three possible reasons of short-circuiting in an electric circuit. (ii) In case of overload, will the fuse protect to given electric circuit from damage ? Justify your answer. (iii) For an electric heater rated as 220 V, 2200 W, what should be the minimum rating of fuse used with it ? ____________ { } 31/5/3 Page 32 of 32 1191-3', 'short_answer', 3, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'State the role of fuse and earthing in domestic electric circuit. Suggest any two precautions to be taken to avoid electrical accidents. 3 [ ] 31(B) Page 24 of 27', 'short_answer', 4, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Read the following passage and answer the questions that follow : H.C. Oersted demonstrated that every current -carrying wire produces magnetic field around it. The pattern of the magnetic field depends upon the geometrical structure the current carrying wire is folded into. When a current -carrying wire is kept in a magnetic field, it experiences a force. Magnitude of this force is maximum when direction of magnetic field is at right angle s to the current-carrying wire. Some rules to determine the direction of magnetic field and force were given by scientists Maxwell and Fleming. (a) What is the direction of magnetic field inside and outside a solenoid ? 1 (b) Same electric current is flowing through three identical wires A, B and C. If wires A, B and C are making respectively angles 30 °, 60 ° and 270 ° with the magnetic field, which of the wire s will experience maximum force and why ? 1 (c) (i) Name and state the law which is required to find out the direction of force acting on a current carrying wire, kept in a magnetic field. 2 OR (c) (ii) Name and state the law which is required to find out the direction of magnetic field around the current carrying straight conductor. 2', 'short_answer', 2, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Attempt either (a) or (b) : (a) (i) State the rule which gives the direction of force acting on a current-carrying conductor placed in a magnetic field. (ii) What is a fuse ? Why is it called a safety device ? (iii) Why are electrical appliances with metallic bodies connected to the mains through a three -pin plug, whereas an electric bulb is connected with a two-pin plug ? [ ] 31/2/1 Page 30 of 31 (iv) [ ] 31/2/1 Page 31 of 31 P.T.O. (iv) What will be the direction of force experienced by the conductor AB due to the magnetic field, when current flows in the direction shown ? Name the law you applied to find the direction. 5 OR (b) (i) Draw the pattern of magnetic field lines through and around a current-carrying circular loop. (ii) State the rule to find out the direction of the magnetic field inside and around the circular loop. (iii) Give reasons : (I) Why should a burnt -out fuse be replaced by another fuse of identical rating only, in an electric circuit ? (II) Why is soft iron-core used in making an electromagnet ? 5', 'short_answer', 5, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(a) (i) State the rules to determine the following : (I) Direction of magnetic field produced around a current-carrying straight conductor. (II) Direction of force experienced by a current -carrying straight conductor placed in a magnetic field which is perpendicular to it. (ii) (I) Draw the magnetic field lines due to a current -carrying solenoid. [ ] 31/2/2 Page 30 of 31 (II) [ ] 31/2/2 Page 31 of 31 P.T.O. (II) Three points A, B and C are marked in the above given diagram of the current -carrying solenoid. Out of the three points A, B and C, at which point is the magnetic field strength maximum and at which point is it minimum ? 5 OR (b) (i) (I) In t he given circuit diagram, a battery B, a key K, a resistance R and a thick copper wire XY are connected in series and a compass is placed near the wire. What is the purpose of this arrangement ? (II) What conclusion do you draw from it ? (ii) Give reasons : (I) There is either a convergence or a divergence of magnetic field lines near the ends of a current -carrying straight solenoid. (II) The current -carrying solenoid, when suspended freely, aligns along a particular direction. (III) The burnt-out fuse should be replaced by another fuse of identical rating. 5', 'short_answer', 5, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(a) (i) The magnetic field lines due to two bar magnets X and Y are shown in the given diagram. If the magnet X is displaced towards magnet Y, will there be repulsion or attraction between them ? Justify. (ii) A metallic conductor is suspended perpendicular to the magnetic field of a horseshoe magnet. The conductor gets displaced towards the left when a current is passed through it. What will be the effect on displacement of conductor if the : (I) Current through the conductor is increased ? (II) Horseshoe magnet is replaced by another stronger horseshoe magnet ? (III) Direction of current through the conductor is reversed ? 5 OR [ ] 31/2/3 Page 30 of 31 [ ] 31/2/3 Page 31 of 31 P.T.O. (b) (i) Draw a schematic diagram of a domestic electric circuit which includes the following devices : (I) A fuse (II) A power meter (III) One light point (IV) A power plug (ii) Why is it necessary to connect an earth wire to the electrical appliances having metallic covers ? 5', 'short_answer', 5, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Attempt either (a) or (b) : (a) (i) What is a solenoid ? Draw a diagram showing the magnetic field pattern due to a current-carrying solenoid ( inside and outside). (ii) Name any two factors on which the magnitude of the magnetic field due to a current-carrying solenoid depends. [ ] 31/3/1 Page 30 of 31 [ ] 31/3/1 Page 31 of 31 P.T.O. (iii) A current-carrying solenoid is stretched and converted into a straight wire carrying current. Draw a diagram showing the magnetic field pattern around it and mark the direction of the magnetic field. 5 OR (b) (i) With the help of a diagram, show that a current -carrying conductor placed in an external magnetic field, experiences a force. Indicate the direction of the field, current and force clearly. (ii) The diagram given below shows an electron moving in a uniform magnetic field. (I) What will be the direction of the force acting on the electron ? (II) What will happen to the direction of the force acting on the electron , if the direction of the magnetic field as well as the direction of motion of the electron , both are reversed ? 5', 'short_answer', 5, '2026', 'medium');
