        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'The resistivity of a wire made of an alloy is generally : (A) Lower than that of its constituent metals. (B) Higher than that of its constituent metals. (C) Decreases with increase in its area of cross-section. (D) Increases with increase in its length.', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Assertion (A) : Ductility is that property of metals which en ables copper to be used in making cooking utensils. Reason (R) : Copper is a metal which is ductile as well as malleable.', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Assertion (A) : Brass is prepared by first melting copper and then dissolving tin into it in a definite proportion. Reason (R) : The primary metal of brass is copper.', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Attempt either option (A) or (B). (A) (i) Which method will be used to convert each of them to their respective metal oxides ? (a) Carbonate ore (b) Sulphide ore (ii) Write a chemical reaction to illustrate the use of aluminium for joining cracked railway tracks. (iii) During extraction of metals, electrolytic refining is used to obtain pure metals. Which material will be used as anode and cathode for the refining of copper metal by this process ? 3 OR (B) (i) Write all the reactions involved in the extraction of Zn from ZnS. (ii) Hydrogen gas is not evolved when most of the metals react with nitric acid. Give reason. 2+1', 'short_answer', 1, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Solder is an alloy of 1 (A) copper and zinc (B) lead and zinc (C) lead and tin (D) copper and tin', 'short_answer', 2, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Read the following passage and answer the questions that follow : When metals are burnt in air, they form oxides. Metal oxides are generally basic in nature. But some metal oxides show both acidic as well as basic behaviour. Most metal oxides are insoluble in water, but some of these dissolve in water to form alkalis. Different metals show different reactivities towards oxygen. Metals such as sodium and potassium react vigorously whereas metals like silver and gold do not react with oxygen even at high temperature. (a) Why are metals like sodium and potassium kept immersed in kerosene oil ? 1 (b) Why does copper metal turn black on heating ? 1 (c) (i) What are the amphoteric oxides ? Give two examples. 2 OR (c) (ii) (I) Name a water soluble metal oxide. Write the chemical equation for its reaction with water. (II) Why do silver and gold not react with oxygen even at high temperature ? 2', 'short_answer', 2, '2026', 'medium');
