        VALUES (v_quiz_id, 'The second member of alkyne homologous series is : 1 (A) propene (B) ethyne (C) ethene (D) propyne For Question number 24, two statements are given — one labelled as Assertion (A) and the other labelled as Reason (R). Select the correct answer to this question from the codes (A), (B), (C) and (D) as given below. (A) Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of Assertion (A). (B) Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of Assertion (A). (C) Assertion (A) is true, but Reason (R) is false. (D) Assertion (A) is false, but Reason (R) is true. [ ] 31(B) Page 16 of 27', 'short_answer', 2, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Attempt either subpart (a) or (b) : (a) (i) Define catenation. Why does carbon show catenation ? (ii) Define homologous series. Give examples of two homologues whose molecular mass differ by 14 amu. (iii) Why do soaps not work well in hard water ? 2+2+1=5 OR (b) (i) Why do covalent compounds have low melting and boiling points ? (ii) Name the reagent that can convert ethanol to ethanoic acid. (iii) Why is ethanoic acid a weaker acid than mineral acids ? (iv) Define esterification reaction. (v) What are ‘Micelles’ ? 51=5 [ ] 31(B) Page 20 of 27', 'short_answer', 3, '2026', 'medium');
