        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Consider the structures ‘X’ and ‘Y’ given below : HHHH – C – C – C – C – HH HHHH   and H – –CH H HH – C –– C – – C – H H H H H      ‘X’ ‘Y’ Which of the following statements are correct ? 1 (i) ‘X’ and ‘Y’ are homologues. (ii) ‘X’ and ‘Y’ have the same structural formula , but different molecular formula. (iii) ‘X’ and ‘Y’ have the same molecular formula , but different structural formula. (iv) ‘X’ and ‘Y’ are structural isomers. (A) (i) and (iii) (B) (i) and (iv) (C) (ii) and (iv) (D) (iii) and (iv) [ ] 31/3/1 Page 16 of 31', 'short_answer', 1, '2026', 'medium');
